// The model answers with JSON only (the system prompt says so), but a
// stray code fence is the one deviation worth surviving — everything else
// is left to fail loudly here rather than reach the variant store.
const text = $input.first().json.content
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();

const json = text.replace(/^```(?:json)?\s*/, '').replace(/```$/, '');
const draft = JSON.parse(json);

const body = $('Webhook').first().json.body;

return [{
  json: {
    profileId: body.profileId,
    variantId: body.variantId,
    tag: draft.tag,
    label: draft.label,
    sections: draft.sections,
  },
}];
